}
import * as SecureStore from 'expo-secure-store';
import { Platform } from 'react-native';

export async function isSecureStorageAvailable(): Promise<boolean> {
  return Platform.OS !== 'web' && (await SecureStore.isAvailableAsync());
}

export async function setSecureItem(key: string, value: string): Promise<void> {
  if (!(await isSecureStorageAvailable())) {
    throw new Error('Secure storage is unavailable on this platform');
  }

  await SecureStore.setItemAsync(key, value);
}

export async function getSecureItem(key: string): Promise<string | null> {
  if (!(await isSecureStorageAvailable())) {
    return null;
  }

  return SecureStore.getItemAsync(key);
}

export async function removeSecureItem(key: string): Promise<void> {
  if (!(await isSecureStorageAvailable())) {
    return;
  }

  await SecureStore.deleteItemAsync(key);
}
/**
 * Storage Service
 * AsyncStorage wrapper with JSON serialization and TypeScript support
 */
import AsyncStorage from '@react-native-async-storage/async-storage';
import { logger } from '@/shared/lib/logger';

// Common storage keys used across the app
export const STORAGE_KEYS = {
  AUTH_TOKEN: 'auth_token',
  USER_DATA: 'user_data',
} as const;

/**
 * Store a value in AsyncStorage with JSON serialization
 */
export async function setItem<T>(key: string, value: T): Promise<void> {
  try {
    const jsonValue = JSON.stringify(value);
    await AsyncStorage.setItem(key, jsonValue);
  } catch (error) {
    logger.error(`Error storing ${key}`, error);
    throw error;
  }
}

/**
 * Retrieve a value from AsyncStorage with JSON deserialization
 */
export async function getItem<T>(key: string): Promise<T | null> {
  try {
    const jsonValue = await AsyncStorage.getItem(key);
    return jsonValue != null ? (JSON.parse(jsonValue) as T) : null;
  } catch (error) {
    logger.error(`Error retrieving ${key}`, error);
    return null;
  }
}

/**
 * Remove a specific item from AsyncStorage
 */
export async function removeItem(key: string): Promise<void> {
  try {
    await AsyncStorage.removeItem(key);
  } catch (error) {
    logger.error(`Error removing ${key}`, error);
    throw error;
  }
}
/**
 * Where the auth token lives.
 *
 * - iOS / Android: the platform keychain / keystore via expo-secure-store,
 *   so the session survives app restarts.
 * - Web: memory only. Browsers have no storage that page scripts can read
 *   but an XSS payload cannot, so the token is not written to localStorage or
 *   sessionStorage; a reload signs the user out. For sessions that survive a
 *   reload on web, have your backend set an httpOnly cookie and register a
 *   matching store with setTokenStore() (see docs/api-and-storage.md).
 */
import { Platform } from 'react-native';
import {
  getSecureItem,
  removeSecureItem,
  setSecureItem,
} from '@/shared/storage/secureStorage';
import { STORAGE_KEYS } from '@/shared/storage/storage';

export interface TokenStore {
  /** The stored token, or null when signed out. */
  get(): Promise<string | null>;
  set(token: string): Promise<void>;
  clear(): Promise<void>;
  /** True when the token survives an app restart or page reload. */
  readonly persistent: boolean;
}

/** Native store backed by expo-secure-store. */
export function createSecureTokenStore(
  key: string = STORAGE_KEYS.AUTH_TOKEN
): TokenStore {
  return {
    persistent: true,
    get: () => getSecureItem(key),
    set: token => setSecureItem(key, token),
    clear: () => removeSecureItem(key),
  };
}

/** In-memory store: the token is lost when the page or app is reloaded. */
export function createMemoryTokenStore(): TokenStore {
  let token: string | null = null;
  return {
    persistent: false,
    get: async () => token,
    set: async value => {
      token = value;
    },
    clear: async () => {
      token = null;
    },
  };
}

/** The default store for a platform: memory on web, secure storage elsewhere. */
export function createTokenStore(
  platform: typeof Platform.OS = Platform.OS
): TokenStore {
  return platform === 'web'
    ? createMemoryTokenStore()
    : createSecureTokenStore();
}

const defaultTokenStore = createTokenStore();
let currentTokenStore: TokenStore = defaultTokenStore;

/** The active token store. */
export function getTokenStore(): TokenStore {
  return currentTokenStore;
}

/** Replaces the token store, or restores the platform default with null. */
export function setTokenStore(store: TokenStore | null): void {
  currentTokenStore = store ?? defaultTokenStore;
}
/**
 * Loads data for a screen: runs an async function on mount and whenever
 * `deps` change, and tracks loading, data, and a typed error.
 *
 * - `fetchFn` gets an AbortSignal; pass it to the request
 *   (`api.get(url, { signal })`). The previous request is aborted when deps
 *   change, on refetch, and on unmount.
 * - Only the latest request updates state, so a slow, outdated response can't
 *   overwrite a newer one (even if the server ignores the abort).
 * - `error` is an ApiError (`code`, `status`, `message`), or null.
 *
 * For caching, background refetching, and mutations, use a data library
 * instead; see docs/api-and-storage.md#loading-data-in-screens.
 */
import {
  useCallback,
  useEffect,
  useRef,
  useState,
  type DependencyList,
} from 'react';
import { toApiError, type ApiError } from '@/shared/http/apiError';

export interface UseFetchResult<T> {
  data: T | null;
  loading: boolean;
  error: ApiError | null;
  /** Runs the request again (aborting one in flight). */
  refetch: () => Promise<void>;
}

function sameDeps(a: DependencyList, b: DependencyList): boolean {
  return a.length === b.length && a.every((value, i) => Object.is(value, b[i]));
}

/**
 * @example
 * const { data, loading, error, refetch } = useFetch(
 *   signal => postsApi.list({ signal }),
 *   [userId]
 * );
 */
export function useFetch<T>(
  fetchFn: (signal: AbortSignal) => Promise<T>,
  deps: DependencyList = []
): UseFetchResult<T> {
  const [data, setData] = useState<T | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<ApiError | null>(null);

  // Re-run when deps change, compared item by item like a hook's deps. The
  // previous deps are kept in state (React's "information from previous
  // renders" pattern) so callers can pass their own dependency list.
  const [trackedDeps, setTrackedDeps] = useState(deps);
  const [depsVersion, setDepsVersion] = useState(0);
  if (!sameDeps(trackedDeps, deps)) {
    setTrackedDeps(deps);
    setDepsVersion(version => version + 1);
  }

  // The latest fetchFn, without making it a dependency (callers usually pass
  // an inline function).
  const fetchFnRef = useRef(fetchFn);
  useEffect(() => {
    fetchFnRef.current = fetchFn;
  });

  const controllerRef = useRef<AbortController | null>(null);

  const run = useCallback(async () => {
    controllerRef.current?.abort();
    const controller = new AbortController();
    controllerRef.current = controller;
    const isCurrent = () =>
      controllerRef.current === controller && !controller.signal.aborted;

    setLoading(true);
    setError(null);
    try {
      const result = await fetchFnRef.current(controller.signal);
      if (isCurrent()) setData(result);
    } catch (caught) {
      if (isCurrent()) {
        setError(toApiError(caught));
        setData(null);
      }
    } finally {
      if (isCurrent()) setLoading(false);
    }
  }, []);

  useEffect(() => {
    void run();
    return () => {
      // Unmount or deps change: drop the request and its result.
      controllerRef.current?.abort();
    };
  }, [run, depsVersion]);

  return { data, loading, error, refetch: run };
}

