  env: { ...process.env, PORT: String(port) },
  stdio: 'inherit',
});

async function call(method, url, { body, token } = {}) {
  const res = await fetch(base + url, {
    method,
    headers: {
      'Content-Type': 'application/json',
      ...(token ? { Authorization: `Bearer ${token}` } : {}),
    },
    body: body ? JSON.stringify(body) : undefined,
  });
  const text = await res.text();
  console.log(method, url, res.status, text);
  return text ? JSON.parse(text) : null;
}

(async () => {
  await new Promise(r => setTimeout(r, 500));
  try {
    await call('POST', '/sessions', { body: { email: 'field@example.com', password: 'x' } });
    const s = await call('POST', '/sessions', { body: { email: 'field@example.com', password: 'notes-123' } });
    const { access_token: at, refresh_token: rt } = s.data;
    await call('GET', '/me');
    await call('GET', '/me', { token: at });
    await call('GET', '/notes', { token: at });
    fs.writeFileSync(path.join(root, 'mock-backend/.fail'), '');
    await call('GET', '/notes', { token: at });
    fs.unlinkSync(path.join(root, 'mock-backend/.fail'));
    await call('POST', '/sessions/refresh', { body: { refresh_token: rt } });
