/**
 * The one place to plug real providers into the integration seams.
 *
 * Every seam already has a default that works without accounts or native
 * setup: analytics logs at debug level, feature flags read
 * shared/config/featureFlags.ts, push and OTA updates report "not configured",
 * i18n serves English, and the error reporter writes to the console. To use
 * a provider, install it and register an adapter in configureIntegrations(),
 * for example:
 *
 *   import { analyticsSeam } from './analytics';
 *   import { createPostHogAnalytics } from './adapters/posthog';
 *
 *   analyticsSeam.set(createPostHogAnalytics(client));
 *
 * docs/plug-in-a-provider.md has an example adapter for each seam, and
 * docs/error-reporting.md one for the error reporter. This function
 * runs once, from app/_layout.tsx, before the first screen renders.
 */

let configured = false;

export function configureIntegrations(): void {
  if (configured) return;
  configured = true;

  // Register provider adapters here. Without them the defaults stay active.

  // Sign-in against the Field Notes backend (docs/connect-your-backend.md).
  setAuthAdapter(fieldNotesAuthAdapter);
}

import { useRef, useState } from 'react';
import {
  KeyboardAvoidingView,
  Platform,
  ScrollView,
  StyleSheet,
  View,
  type TextInput as NativeTextInput,
} from 'react-native';
import { SafeAreaView } from 'react-native-safe-area-context';
import {
  Text,
  TextInput,
  Button,
  useTheme,
  Snackbar,
} from 'react-native-paper';
import { useSession } from '@/shared/session/SessionProvider';
import { t } from '@/shared/i18n';

export function LoginScreen() {
  const theme = useTheme();
  const [username, setUsername] = useState('');
  const [password, setPassword] = useState('');
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [snackbarVisible, setSnackbarVisible] = useState(false);
  const passwordRef = useRef<NativeTextInput>(null);
  const { signIn } = useSession();

  const handleLogin = async () => {
    if (!username || !password) {
      setError(t('login.error.emptyFields'));
      setSnackbarVisible(true);
      return;
    }

    setLoading(true);
    setError(null);

    try {
      // Signing in flips the route guards in app/_layout.tsx: this screen
      // (signed-out only) is removed and the app returns to Home.
      await signIn({ username, password });
    } catch (err) {
      const errorMessage =
        err instanceof Error ? err.message : t('login.error.generic');
      setError(errorMessage);
      setSnackbarVisible(true);
    } finally {
      setLoading(false);
    }
  };

  return (
    <SafeAreaView
      style={[styles.container, { backgroundColor: theme.colors.background }]}
    >
      <KeyboardAvoidingView
        style={styles.container}
        behavior={Platform.OS === 'ios' ? 'padding' : 'height'}
      >
        <ScrollView
          contentContainerStyle={styles.content}
          keyboardShouldPersistTaps="handled"
        >
          <View style={styles.header}>
            <Text variant="headlineMedium" style={styles.title}>
              {t('login.title')}
            </Text>
            <Text
              variant="bodyMedium"
              style={{ color: theme.colors.onSurfaceVariant }}
            >
              {t('login.subtitle')}
            </Text>
          </View>

          <View style={styles.form}>
            <TextInput
              label={t('login.username')}
              value={username}
              onChangeText={setUsername}
              mode="outlined"
              autoCapitalize="none"
              autoComplete="username"
              returnKeyType="next"
              submitBehavior="submit"
              onSubmitEditing={() => passwordRef.current?.focus()}
              style={styles.input}
              testID="login-username"
            />

            <TextInput
              ref={passwordRef}
              label={t('login.password')}
              value={password}
              onChangeText={setPassword}
              mode="outlined"
              secureTextEntry
              autoCapitalize="none"
              autoComplete="password"
              returnKeyType="go"
              onSubmitEditing={handleLogin}
              style={styles.input}
              testID="login-password"
            />

            <Button
              mode="contained"
              onPress={handleLogin}
              loading={loading}
              disabled={loading}
              style={styles.button}
              testID="login-submit"
            >
              {t('login.submit')}
            </Button>
          </View>
        </ScrollView>
      </KeyboardAvoidingView>

      <Snackbar
        visible={snackbarVisible}
        onDismiss={() => setSnackbarVisible(false)}
        duration={4000}
        action={{
          label: t('common.dismiss'),
          onPress: () => setSnackbarVisible(false),
        }}
      >
        {error || t('common.unknownError')}
      </Snackbar>
    </SafeAreaView>
  );
}

const styles = StyleSheet.create({
  container: {
    flex: 1,
  },
  content: {
    flexGrow: 1,
    padding: 24,
    justifyContent: 'center',
  },
  header: {
    marginBottom: 32,
    alignItems: 'center',
  },
  title: {
    marginBottom: 8,
    fontWeight: 'bold',
  },
  form: {
    width: '100%',
  },
  input: {
    marginBottom: 16,
  },
  button: {
    marginTop: 8,
    marginBottom: 16,
  },
});

