/**
 * In-memory expo-secure-store for tests. jest.setup.ts installs it for every
 * test file and empties it before each test. Inspect or seed it directly:
 *
 *   secureStore.set(STORAGE_KEYS.AUTH_TOKEN, 'stored-token');
 *   expect(secureStore.has(STORAGE_KEYS.AUTH_TOKEN)).toBe(false);
 *
 * The module functions are jest.fn()s, so tests can still override one call,
 * e.g. jest.mocked(SecureStore.getItemAsync).mockRejectedValueOnce(error).
 */
export const secureStore = new Map<string, string>();

export const secureStoreModule = {
  isAvailableAsync: jest.fn(),
  setItemAsync: jest.fn(),
  getItemAsync: jest.fn(),
  deleteItemAsync: jest.fn(),
};

/** Empties the store and restores the default (available, stateful) behavior. */
export function resetSecureStore(): void {
  secureStore.clear();
  secureStoreModule.isAvailableAsync
    .mockReset()
    .mockImplementation(() => Promise.resolve(true));
  secureStoreModule.setItemAsync
    .mockReset()
    .mockImplementation((key: string, value: string) => {
      secureStore.set(key, value);
      return Promise.resolve();
    });
  secureStoreModule.getItemAsync
    .mockReset()
    .mockImplementation((key: string) =>
      Promise.resolve(secureStore.get(key) ?? null)
    );
  secureStoreModule.deleteItemAsync
    .mockReset()
    .mockImplementation((key: string) => {
      secureStore.delete(key);
      return Promise.resolve();
    });
}
import {
  AxiosError,
  AxiosHeaders,
  CanceledError,
  type AxiosAdapter,
  type InternalAxiosRequestConfig,
} from 'axios';
import { ApiError, toApiError } from '@/shared/http/apiError';
import { createHttpClient } from '@/shared/http/httpClient';
import {
  onSessionExpired,
  setRefreshTokenHandler,
  setUnauthorizedHandler,
} from '@/shared/session/session';
import {
  authClients,
  authService,
  setAuthAdapter,
  type AuthAdapter,
} from '@/shared/session/authService';

const authApi = authClients.public;

/** Minimal adapter: POST /auth/login → { accessToken, id, email }. */
const testAuthAdapter: AuthAdapter = {
  login: async (credentials, { public: http }) => {
    const { data } = await http.post('/auth/login', credentials);
    return { token: data.accessToken, user: data };
  },
  normalizeUser: raw => {
    const data = raw as { id: number; email: string };
    return { id: data.id, email: data.email, name: data.email };
  },
};
import { getItem, setItem, STORAGE_KEYS } from '@/shared/storage/storage';
import { DEFAULT_API_TIMEOUT_MS, getConfig } from '@/shared/config/env';
import { secureStore } from '@/testing';

jest.mock('@/shared/lib/logger', () => ({
  logger: {
    warn: jest.fn(),
    error: jest.fn(),
    info: jest.fn(),
    debug: jest.fn(),
  },
}));

const user = { id: 1, email: 'e@example.com', name: 'Emily' };

function response(
  config: InternalAxiosRequestConfig,
  status: number,
  data: unknown = {}
) {
  return { config, status, data, statusText: String(status), headers: {} };
}

function httpError(
  config: InternalAxiosRequestConfig,
  status: number,
  data: unknown = {}
) {
  return new AxiosError(
    `Request failed with status code ${status}`,
    status >= 500 ? 'ERR_BAD_RESPONSE' : 'ERR_BAD_REQUEST',
    config,
    undefined,
    response(config, status, data)
  );
}

/** A client whose base URL is the auth origin, so the token is attached. */
function authenticatedClient(adapter: AxiosAdapter) {
  const client = createHttpClient({
    getBaseURL: () => getConfig().authApiUrl,
    authenticated: true,
  });
  client.defaults.adapter = adapter;
  return client;
}

