/**
 * LoadingScreen Component
 * Simple reusable loading component with centered ActivityIndicator
 */
import React from 'react';
import { View, StyleSheet } from 'react-native';
import { ActivityIndicator, Text, useTheme } from 'react-native-paper';

interface LoadingScreenProps {
  message?: string;
}

/**
 * LoadingScreen displays a centered loading indicator with optional message.
 *
 * @example
 * ```tsx
 * <LoadingScreen message="Loading data..." />
 * ```
 */
export function LoadingScreen({ message }: LoadingScreenProps) {
  const theme = useTheme();

  return (
    <View
      style={[styles.container, { backgroundColor: theme.colors.background }]}
      testID="loading-screen"
    >
      <ActivityIndicator size="large" color={theme.colors.primary} />
      {message && (
        <Text
          variant="bodyMedium"
          style={[styles.message, { color: theme.colors.onSurfaceVariant }]}
        >
          {message}
        </Text>
      )}
    </View>
  );
}

const styles = StyleSheet.create({
  container: {
    flex: 1,
    justifyContent: 'center',
    alignItems: 'center',
    padding: 16,
  },
  message: {
    marginTop: 16,
  },
});
import { ScrollView, StyleSheet, View } from 'react-native';
import { SafeAreaView } from 'react-native-safe-area-context';
import { Button, Card, Text, useTheme } from 'react-native-paper';
import { router } from 'expo-router';
import { useSession } from '@/shared/session/SessionProvider';
import { t } from '@/shared/i18n';

/** Home: the session card and links to the examples. */
export function HomeScreen() {
  const theme = useTheme();
  const { session, signOut } = useSession();

  return (
    <SafeAreaView
      style={[styles.container, { backgroundColor: theme.colors.background }]}
    >
      <ScrollView contentContainerStyle={styles.content}>
        <Text variant="headlineMedium" style={styles.title}>
          {t('home.title')}
        </Text>

        <Card mode="outlined" style={styles.card}>
          <Card.Content>
            <Text variant="titleMedium">{t('home.session.title')}</Text>
            <Text
              variant="bodyMedium"
              style={[styles.status, { color: theme.colors.onSurfaceVariant }]}
              testID="session-status"
            >
              {session.status === 'loading'
                ? t('home.session.checking')
                : session.status === 'signedIn'
                  ? t('home.session.signedIn', {
                      name:
                        session.user?.name ??
                        t('home.session.signedInFallbackName'),
                    })
                  : t('home.session.signedOut')}
            </Text>
          </Card.Content>
          <Card.Actions>
            {session.status === 'signedIn' ? (
              <View style={styles.actions}>
                <Button
                  mode="outlined"
                  onPress={signOut}
                  testID="logout-button"
                >
                  {t('home.session.logOut')}
                </Button>
                <Button
                  mode="contained-tonal"
                  onPress={() => router.push('/profile')}
                  testID="profile-button"
                >
                  {t('home.session.viewProfile')}
                </Button>
              </View>
            ) : (
              <Button
                mode="contained"
                onPress={() => router.push('/login')}
                disabled={session.status === 'loading'}
                testID="sign-in-button"
              >
                {t('home.session.signIn')}
              </Button>
            )}
          </Card.Actions>
        </Card>
      </ScrollView>
    </SafeAreaView>
  );
}

const styles = StyleSheet.create({
  container: {
    flex: 1,
  },
  content: {
    padding: 16,
  },
  title: {
