import { StyleSheet, View } from 'react-native';
import { SafeAreaView } from 'react-native-safe-area-context';
import { Button, Text, useTheme } from 'react-native-paper';
import { router } from 'expo-router';
import { useSession } from '@/shared/session/SessionProvider';
import { t } from '@/shared/i18n';
import { NotesList } from '../components/NotesList';

/**
 * The Notes tab. Notes belong to the signed-in user, so a signed-out user
 * gets a sign-in prompt instead of a request that would fail with a 401.
 */
export function NotesScreen() {
  const theme = useTheme();
  const { session } = useSession();

  return (
    <SafeAreaView
      edges={['top', 'left', 'right']}
      style={[styles.container, { backgroundColor: theme.colors.background }]}
    >
      <Text variant="headlineMedium" style={styles.title}>
        {t('notes.title')}
      </Text>
      {session.status === 'signedIn' ? (
        <NotesList />
      ) : (
        <View style={styles.signedOut}>
          <Text
            variant="bodyMedium"
            style={[styles.prompt, { color: theme.colors.onSurfaceVariant }]}
          >
            {t('notes.signedOut')}
          </Text>
          <Button
            mode="contained"
            onPress={() => router.push('/login')}
            testID="notes-sign-in"
          >
            {t('home.session.signIn')}
          </Button>
        </View>
      )}
    </SafeAreaView>
  );
}

