/**
 * A fake analytics provider: keeps every call in memory and logs it. Stands
 * in for a real SDK until one is chosen, and lets tests and debugging see
 * exactly what the app reported. Registered in shared/integrations/setup.ts.
 */
import { logger } from '@/shared/lib/logger';
import type { Analytics, AnalyticsProperties } from '../analytics';

export type RecordedAnalyticsEvent =
  | { type: 'track'; name: string; properties: AnalyticsProperties | null }
  | { type: 'screen'; name: string; properties: AnalyticsProperties | null }
  | {
      type: 'identify';
      userId: string | null;
      traits: AnalyticsProperties | null;
    };

export interface MemoryAnalytics extends Analytics {
  /** Everything recorded so far, oldest first (at most `limit` entries). */
  readonly events: readonly RecordedAnalyticsEvent[];
  clear(): void;
}

/** `limit` caps memory use in a long session; older events are dropped. */
export function createMemoryAnalytics(limit = 500): MemoryAnalytics {
  const events: RecordedAnalyticsEvent[] = [];
  const record = (event: RecordedAnalyticsEvent) => {
    events.push(event);
    if (events.length > limit) events.splice(0, events.length - limit);
    const { type, ...rest } = event;
    logger.info(`[analytics:memory] ${type}`, rest);
  };

  return {
    events,
    clear: () => {
      events.length = 0;
    },
    track: (name, properties) =>
      record({ type: 'track', name, properties: properties ?? null }),
    screen: (name, properties) =>
      record({ type: 'screen', name, properties: properties ?? null }),
    identify: (userId, traits) =>
      record({ type: 'identify', userId, traits: traits ?? null }),
  };
}

import {
  createMemoryAnalytics,
  type MemoryAnalytics,
} from '@/shared/integrations/adapters/memoryAnalytics';
import { analyticsSeam, getAnalytics } from '@/shared/integrations/analytics';
import { configureIntegrations } from '@/shared/integrations/setup';
import { logger } from '@/shared/lib/logger';

jest.mock('@/shared/lib/logger', () => ({
  logger: {
    warn: jest.fn(),
    error: jest.fn(),
    info: jest.fn(),
    debug: jest.fn(),
  },
}));

describe('memory analytics', () => {
  afterEach(() => analyticsSeam.reset());

  it('records track, screen, and identify calls in order and logs each one', () => {
    const analytics = createMemoryAnalytics();

    analytics.screen('/notes');
    analytics.track('notes_loaded', { count: 3 });
    analytics.identify('u_1', { plan: 'free' });
    analytics.identify(null);

    expect(analytics.events).toEqual([
      { type: 'screen', name: '/notes', properties: null },
      { type: 'track', name: 'notes_loaded', properties: { count: 3 } },
      { type: 'identify', userId: 'u_1', traits: { plan: 'free' } },
      { type: 'identify', userId: null, traits: null },
    ]);
    expect(logger.info).toHaveBeenCalledWith('[analytics:memory] track', {
      name: 'notes_loaded',
      properties: { count: 3 },
    });
  });

  it('keeps only the newest events up to the limit, and clears', () => {
    const analytics = createMemoryAnalytics(2);

    analytics.track('a');
    analytics.track('b');
    analytics.track('c');
    expect(
      analytics.events.map(e => (e.type === 'track' ? e.name : ''))
    ).toEqual(['b', 'c']);

    analytics.clear();
    expect(analytics.events).toEqual([]);
  });

  it('is the analytics provider the app registers', () => {
    configureIntegrations();
    const analytics = getAnalytics() as Partial<MemoryAnalytics>;

    analytics.track?.('probe');

    expect(analytics.events).toContainEqual({
      type: 'track',
      name: 'probe',
      properties: null,
    });
  });
});

